-- sante-intervention-conjointe-samu-pompiers — Trois services sur place, personne ne pilote
SELECT public.fn_cp_import_case('sante-intervention-conjointe-samu-pompiers', '{"slug": "sante-intervention-conjointe-samu-pompiers", "title": "Trois services sur place, personne ne pilote", "theme_slug": "secours-personnes", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 20 heures. Vous arrivez au domicile d''une personne en crise psychique aigue, en meme temps qu''une equipe du SAMU et des pompiers, tous trois appeles independamment par des voisins differents. Sur le palier exigu, chaque service commence a donner ses instructions sans concertation prealable, et la personne en crise, deja tres agitee, recoit trois discours simultanes et parfois contradictoires. Aucun service ne prend explicitement la coordination de cette intervention a trois, chacun agissant selon sa propre logique professionnelle. La tension monte, tant chez la personne en crise que dans l''espace reduit ou s''entassent desormais six intervenants.", "questions": [{"position": 1, "max_points": 5, "label": "Comment intervenez-vous face a cette absence de pilotage entre les trois services presents ?", "hint": "Personne ne pilote ne signifie pas que personne ne peut prendre cette initiative.", "perfect": "Je clarifie les roles et laisse la main au medical, cette crise relevant avant tout d''une reponse sanitaire a laquelle mon role de securisation doit se subordonner. Je propose explicitement que l''equipe medicale devienne l''interlocuteur principal aupres de la personne, les autres intervenants restant en soutien silencieux. Je reduis le nombre de voix qui s''adressent simultanement a cette personne, en invitant les intervenants non essentiels a reculer. Je reste disponible pour la securite sans interferer dans les decisions medicales qui ne relevent pas de ma competence.", "points": [{"position": 1, "label": "Clarifier les roles et laisser la main au medical", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["roles clarifies", "medical prioritaire", "main laissee"]}]}, {"position": 2, "label": "Proposer explicitement que l''equipe medicale devienne l''interlocuteur principal", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coordination active proposee.", "groups": [{"position": 1, "keywords": ["interlocuteur designe", "equipe medicale", "coordination proposee"]}]}, {"position": 3, "label": "Reduire le nombre de voix s''adressant simultanement a la personne", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reduction du bruit relationnel.", "groups": [{"position": 1, "keywords": ["voix reduites", "confusion evitee", "calme recherche"]}]}, {"position": 4, "label": "Rester disponible pour la securite sans interferer dans les decisions medicales", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Respect des competences respectives.", "groups": [{"position": 1, "keywords": ["securite assuree", "decision medicale respectee", "interference evitee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous l''espace physiquement exigu qui ajoute a la tension de cette intervention a six intervenants ?", "hint": "L''encombrement du palier n''est pas neutre pour une personne deja en crise.", "perfect": "Je propose de faire sortir du palier les intervenants dont la presence immediate n''est pas indispensable, cet encombrement aggravant visiblement l''agitation de la personne en crise. Je coordonne cette reorganisation spatiale avec les responsables de chaque service, sans imposer unilateralement une decision qui ne me revient pas seule. Je verifie que les issues restent degagees pour une eventuelle evacuation medicale rapide. Je reste attentive a ce que cette reorganisation ne soit pas percue par la personne comme une nouvelle agitation autour d''elle.", "points": [{"position": 1, "label": "Proposer de faire sortir les intervenants non indispensables", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Reduction de l''encombrement source de tension.", "groups": [{"position": 1, "keywords": ["intervenants ecartes", "espace degage", "encombrement reduit"]}]}, {"position": 2, "label": "Coordonner cette reorganisation avec les responsables de chaque service", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Decision partagee entre services.", "groups": [{"position": 1, "keywords": ["reorganisation coordonnee", "responsables consultes", "decision partagee"]}]}, {"position": 3, "label": "Verifier que les issues restent degagees pour une evacuation eventuelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Anticipation operationnelle.", "groups": [{"position": 1, "keywords": ["issues degagees", "evacuation anticipee", "acces preserve"]}]}, {"position": 4, "label": "Veiller a ce que cette reorganisation ne soit pas percue comme une nouvelle agitation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Attention a la perception de la personne.", "groups": [{"position": 1, "keywords": ["perception menagee", "agitation evitee", "reorganisation discrete"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment tirez-vous les enseignements de cette coordination defaillante pour la suite de votre service ?", "hint": "Cette difficulte de coordination n''est probablement pas propre a cette seule intervention.", "perfect": "Je documente cette intervention en mentionnant explicitement cette difficulte de coordination initiale entre les trois services presents. Je transmets ce constat a ma hierarchie, cette information pouvant utilement nourrir une reflexion sur les protocoles d''intervention conjointe. Je reste factuelle dans cette remontee, sans chercher a designer un responsable de cette confusion initiale. Je retiens pour mes prochaines interventions similaires l''interet de proposer rapidement une clarification des roles des l''arrivee simultanee de plusieurs services.", "points": [{"position": 1, "label": "Documenter cette difficulte de coordination dans le compte rendu", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilite de l''incident organisationnel.", "groups": [{"position": 1, "keywords": ["difficulte documentee", "coordination notee", "compte rendu complet"]}]}, {"position": 2, "label": "Transmettre ce constat a la hierarchie pour nourrir une reflexion", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Remontee utile pour l''avenir.", "groups": [{"position": 1, "keywords": ["hierarchie informee", "reflexion nourrie", "protocole questionne"]}]}, {"position": 3, "label": "Rester factuelle sans designer de responsable de cette confusion", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Neutralite du compte rendu.", "groups": [{"position": 1, "keywords": ["neutralite maintenue", "responsable non designe", "faits rapportes"]}]}, {"position": 4, "label": "Retenir l''interet d''une clarification rapide des roles a l''avenir", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Amelioration personnelle continue.", "groups": [{"position": 1, "keywords": ["lecon retenue", "amelioration continue", "roles clarifies a l''avenir"]}]}]}]}'::jsonb);

-- sante-personne-refuse-tout-contact-verbal — Elle se bouche les oreilles des que vous parlez
SELECT public.fn_cp_import_case('sante-personne-refuse-tout-contact-verbal', '{"slug": "sante-personne-refuse-tout-contact-verbal", "title": "Elle se bouche les oreilles des que vous parlez", "theme_slug": "secours-personnes", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Signalee par un voisin pour des bruits inhabituels, vous trouvez une femme assise dans un coin de son appartement, recroquevillee. Des que vous prononcez un mot, elle se bouche immediatement les oreilles avec les mains et detourne le regard, repetant ce geste a chaque nouvelle tentative de parole de votre part. Elle ne repond a aucune question, ne semble pas non plus en detresse physique visible, mais cette impossibilite totale d''etablir un contact verbal complique considerablement votre evaluation de la situation. Aucune blessure visible, aucun tiers present, aucun element permettant de savoir depuis combien de temps elle se trouve dans cet etat. Le temps passe sans que la situation evolue.", "questions": [{"position": 1, "max_points": 5, "label": "Comment adaptez-vous votre approche face a cette impossibilite totale de communication verbale ?", "hint": "Insister verbalement face a un rejet aussi explicite de la parole ne fera qu''aggraver sa detresse.", "perfect": "Je reduis les stimuli plutot que d''insister verbalement, cette reaction de rejet systematique de la parole appelant une reponse differente de l''insistance. Je baisse le volume de ma voix, voire cesse temporairement de parler, pour observer si cette reduction des stimuli produit un effet different. Je maintiens une presence calme et visible, sans geste brusque, pour ne pas ajouter a sa detresse par ma seule presence physique. J''essaie, si possible, un contact non verbal alternatif, comme l''ecrit ou des gestes simples, plutot que de renoncer a tout contact.", "points": [{"position": 1, "label": "Reduire les stimuli plutot que d''insister verbalement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["stimuli reduits", "insistance evitee", "approche adaptee"]}]}, {"position": 2, "label": "Baisser le volume voire cesser temporairement de parler", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ajustement immediat de la communication.", "groups": [{"position": 1, "keywords": ["volume baisse", "parole suspendue", "silence propose"]}]}, {"position": 3, "label": "Maintenir une presence calme et visible sans geste brusque", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Presence rassurante.", "groups": [{"position": 1, "keywords": ["presence calme", "geste mesure", "brusquerie evitee"]}]}, {"position": 4, "label": "Essayer un contact non verbal alternatif", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Alternative a la parole.", "groups": [{"position": 1, "keywords": ["contact alternatif", "ecrit propose", "gestes utilises"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment evaluez-vous son etat malgre l''absence de toute reponse verbale ou non verbale exploitable ?", "hint": "L''evaluation ne s''arrete pas a l''echec du dialogue.", "perfect": "J''observe attentivement les elements visibles independamment de toute parole : posture, respiration, signes de blessure ou de malaise physique. Je verifie discretement l''environnement pour des indices sur ce qui a pu declencher cet etat, sans fouiller de maniere intrusive. Je sollicite un avis medical compte tenu de cette impossibilite de communication qui ne me permet pas seule d''ecarter une cause grave. Je reste attentive a toute evolution, meme minime, dans son comportement au fil du temps.", "points": [{"position": 1, "label": "Observer attentivement les elements visibles independamment de la parole", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Evaluation non verbale approfondie.", "groups": [{"position": 1, "keywords": ["observation attentive", "elements visibles", "evaluation non verbale"]}]}, {"position": 2, "label": "Verifier discretement l''environnement pour des indices", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recherche d''indices contextuels.", "groups": [{"position": 1, "keywords": ["environnement verifie", "indices recherches", "contexte examine"]}]}, {"position": 3, "label": "Solliciter un avis medical compte tenu de cette impossibilite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Evaluation professionnelle necessaire.", "groups": [{"position": 1, "keywords": ["avis medical", "evaluation sollicitee", "cause grave ecartee"]}]}, {"position": 4, "label": "Rester attentive a toute evolution meme minime", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance continue.", "groups": [{"position": 1, "keywords": ["evolution surveillee", "attention continue", "changement note"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite si cette impossibilite de contact persiste jusqu''a l''arrivee des secours ?", "hint": "Votre role reste utile meme sans avoir pu etablir de dialogue.", "perfect": "Je transmets aux secours medicaux un compte rendu precis de ce que j''ai observe, y compris cette impossibilite totale de communication verbale rencontree. Je reste presente jusqu''a leur arrivee, meme sans echange possible avec elle, cette presence restant en elle-meme une forme de securisation. Je documente cette intervention factuellement, sans interpretation personnelle sur les causes de cet etat. Je reste disponible pour completer l''evaluation medicale si des elements complementaires s''averaient utiles.", "points": [{"position": 1, "label": "Transmettre un compte rendu precis incluant cette impossibilite de communication", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Information complete pour les secours.", "groups": [{"position": 1, "keywords": ["compte rendu transmis", "impossibilite mentionnee", "information complete"]}]}, {"position": 2, "label": "Rester presente jusqu''a l''arrivee des secours malgre l''absence d''echange", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Presence securisante.", "groups": [{"position": 1, "keywords": ["presence maintenue", "securisation assuree", "attente accompagnee"]}]}, {"position": 3, "label": "Documenter factuellement sans interpretation personnelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Objectivite du compte rendu.", "groups": [{"position": 1, "keywords": ["compte rendu factuel", "interpretation evitee", "objectivite maintenue"]}]}, {"position": 4, "label": "Rester disponible pour completer l''evaluation medicale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Collaboration continue avec les secours.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "evaluation completee", "collaboration assuree"]}]}]}]}'::jsonb);

